            var iterator = helpers.iterator();
            while (iterator.hasNext()) {
                var helper = iterator.next();
                if (event.level == helper.player.level()) {
                    if (helper.player.isRemoved() || helper.orderedBlocks.isEmpty() || helper.tool.isEmpty() ||
                            !(hasBehaviorsTag(helper.player.getMainHandItem()) &&
                                    getBehaviorsTag(helper.player.getMainHandItem()).getBoolean(TREE_FELLING_KEY))) {
                        iterator.remove();
                        continue;
                    }
                    if (helper.tick % ConfigHolder.INSTANCE.tools.treeFellingDelay == 0)
                        ToolHelper.breakBlockRoutine(helper.player, helper.tool, helper.orderedBlocks.removeLast(),
                                true);
                    helper.tick++;
                }
            }
        }
    }

@SubscribeEvent
    public static void ServerTickEvents(TickEvent.ServerTickEvent event){
        if (event.phase == TickEvent.Phase.END) {
            Iterator<Pair<String, EventTask>> it = TASKS.iterator();
            Pair<String, EventTask> current;
            while (it.hasNext()) {
                current = it.next();
                try {
                    if (current.getRight().getAsBoolean()) {
                        current.getRight().endTask();
                        it.remove();
                    } else {
                        current.getRight().tickTask();
                    }
                } catch (Exception ex) {
                    Goety.LOGGER.error("An exception occurred while running a ticking task with ID {}.  It will be terminated.", current.getLeft());
                    it.remove();
                }
            }
        }
    }

