public static void handle(PacketTileData message, IPayloadContext ctx) {
    ctx.enqueueWork(() -> {
      ServerPlayer player = (ServerPlayer) ctx.player();
      Level world = player.getCommandSenderWorld();
      BlockEntity tile = world.getBlockEntity(message.pos);
      if (tile instanceof TileBlockEntityCyclic) {
        TileBlockEntityCyclic base = (TileBlockEntityCyclic) tile;
        if (message.autoIncrement) {
          //ignore message.value, do a ++
          int incr = base.getField(message.field) + 1;
          base.setField(message.field, incr);
        }
        else {
          base.setField(message.field, message.value);
        }
        base.setChanged();
      }
    });

  }

protected void checkAndPerformAttack(LivingEntity enemy, boolean inRange) {
        long currentTime = mob.level.getGameTime();
        if (inRange) {
            if (currentTime > attackEndTick + 20) {
                ServerAnimationInfo animationInfo = mob.startAttack();
                if (animationInfo.usesAttackBox && enemy instanceof ServerPlayer player) {
                    MessageHandler.SYNC_CHANNEL.sendToPlayers(List.of(player), new S2CActivateAttackBoxesMessage(mob, animationInfo.animation.animationLength));
                    doingHeavyAttack = true;
                } else {
                    attackDamageTick = (long) (currentTime + animationInfo.actionDelay + 5);
                }
                attackEndTick = (long) (currentTime + animationInfo.animation.animationLength + 5);
                if (attackDamageTick > attackEndTick) attackDamageTick = attackEndTick;
            }
            if (attackDamageTick > 0 && currentTime == attackDamageTick) {
                mob.attackTarget(enemy);
                attackDamageTick = -1;
            }
        }
    }

public void handlerToggleRender(final CPacketToggleRender data, final IPayloadContext ctx) {
    ctx.enqueueWork(() -> {
      Player player = ctx.player();
      CuriosApi.getCuriosInventory(player)
          .flatMap(handler -> handler.getStacksHandler(data.identifier()))
          .ifPresent(stacksHandler -> {
            NonNullList<Boolean> renderStatuses = stacksHandler.getRenders();

            if (renderStatuses.size() > data.index()) {
              boolean value = !renderStatuses.get(data.index());
              renderStatuses.set(data.index(), value);
              PacketDistributor.sendToPlayersTrackingEntityAndSelf(player,
                                                                   new SPacketSyncRender(
                                                                       player.getId(),
                                                                       data.identifier(),
                                                                       data.index(), value));
            }
          });
    });
  }

public static void onServerLevelTick(LevelTickEvent.Pre event) {
        Level level = event.getLevel();
        if (level.isClientSide()) {
            return;
        }

        ResourceKey<Level> dim = level.dimension();
        Long2ObjectMap<LongSet> chunks = UPDATED_POSITIONS.get(dim);
        if (chunks != null && !chunks.isEmpty()) {
            for (Long2ObjectMap.Entry<LongSet> entry : chunks.long2ObjectEntrySet()) {
                long chunk = entry.getLongKey();
                PacketDistributor.sendToPlayersTrackingChunk(
                        (ServerLevel) level,
                        ChunkPos.unpack(chunk),
                        new ClientboundCullingUpdatePayload(chunk, entry.getValue())
                );
            }
            chunks.clear();
        }
    }

