public void hurtEntities(LivingEntity livingEntity){
        ColorUtil colorUtil = new ColorUtil(this.getLightningColor());
        if (this.level instanceof ServerLevel serverLevel) {
            if (livingEntity != null && !livingEntity.isDeadOrDying() && EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(livingEntity)) {
                if (livingEntity.isSensitiveToWater()) {
                    livingEntity.hurt(livingEntity.damageSources().indirectMagic(this, this.getOwner()), 1.0F);
                }
                if (this.random.nextFloat() <= 0.05F) {
                    Vec3 vec3 = this.position();
                    float damage = SpellConfig.ThunderboltDamage.get().floatValue() * WandUtil.damageMultiply();
                    damage += this.getExtraDamage();
                    BlockHitResult rayTraceResult = this.blockResult(serverLevel, this, 16);
                    Optional<BlockPos> lightningRod = BlockFinder.findLightningRod(serverLevel, BlockPos.containing(rayTraceResult.getLocation()), 16);
                    if (lightningRod.isPresent() && !this.isStaff()) {
                        BlockPos blockPos = lightningRod.get();
                        ModNetwork.sendToALL(new SThunderBoltPacket(vec3, new Vec3(blockPos.getX(), blockPos.getY(), blockPos.getZ()), colorUtil, 10));
                        serverLevel.playSound(null, this.getX(), this.getY(), this.getZ(), ModSounds.THUNDERBOLT.get(), this.getSoundSource(), 1.0F, 1.0F);
                    } else {
                        Vec3 vec31 = new Vec3(livingEntity.getX(), livingEntity.getY() + livingEntity.getBbHeight() / 2, livingEntity.getZ());
                        ModNetwork.sendToALL(new SThunderBoltPacket(vec3, vec31, colorUtil, 10));
                        if (livingEntity.hurt(ModDamageSource.indirectShock(this, this.getOwner()), damage)) {
                            float chance = this.isStaff() ? 0.25F : 0.05F;
                            float chainDamage = damage / 2.0F;
                            if (serverLevel.isThundering() && serverLevel.isRainingAt(livingEntity.blockPosition())){
                                chance += 0.25F;
                                chainDamage = damage;
                            }
                            if (serverLevel.getRandom().nextFloat() <= chance){
                                livingEntity.addEffect(new MobEffectInstance(GoetyEffects.SPASMS.get(), MathHelper.secondsToTicks(5)));
                            }
                            if (this.isStaff()){
                                WandUtil.chainLightning(livingEntity, this.getOwner() != null ? this.getOwner() : null, 6.0D, chainDamage);
                            }
                        }
                        serverLevel.playSound(null, this.getX(), this.getY(), this.getZ(), ModSounds.THUNDERBOLT.get(), this.getSoundSource(), 1.0F, 1.0F);
                    }
                }
            }
        }
    }

public void chainCharge(ServerLevel serverLevel, LivingEntity pTarget, LivingEntity pAttacker, double range) {
        List<Entity> harmed = new ArrayList<>();
        Predicate<Entity> selector = entity -> entity instanceof LivingEntity livingEntity && !harmed.contains(livingEntity);
        if (pAttacker != null){
            selector = selector.and(entity -> entity instanceof LivingEntity livingEntity && livingEntity != pAttacker && pTarget instanceof OwnableEntity ownable && ownable.getOwner() == pAttacker);
        }
        Entity prevTarget = pTarget;

        int hops = serverLevel.isThundering() ? 8 : 4;

        for (int i = 0; i < hops; i++) {
            AABB aabb = new AABB(Vec3Util.subtract(prevTarget.position(), range), Vec3Util.add(prevTarget.position(), range));
            Entity finalPrevTarget = prevTarget;
            List<Entity> entities = serverLevel.getEntities(prevTarget, aabb, selector.and(entity -> MobUtil.hasLineOfSight(finalPrevTarget, entity)));
            if (!entities.isEmpty()) {
                Entity entity = entities.get(serverLevel.getRandom().nextInt(entities.size()));
                if (entity instanceof LivingEntity target) {
                    if (!target.hasEffect(GoetyEffects.CHARGED.get())) {
                        this.playSound(serverLevel, target, 1.0F, 0.5F);
                        target.addEffect(new MobEffectInstance(GoetyEffects.CHARGED.get(), MathHelper.secondsToTicks(30), 0, false, false));
                    } else {
                        MobEffectInstance instance = target.getEffect(GoetyEffects.CHARGED.get());
                        if (instance != null) {
                            if (instance.getAmplifier() >= 1) {
                                target.hurt(ModDamageSource.directShock(pAttacker), SpellConfig.ChargeDamage.get().floatValue());
                            } else {
                                this.playSound(serverLevel, target, 1.0F, 0.75F);
                            }
                            EffectsUtil.amplifyEffect(target, GoetyEffects.CHARGED.get(), MathHelper.secondsToTicks(30), 3, false, false);
                        }
                    }
                    if (prevTarget != target) {
                        Vec3 vec3 = prevTarget.getEyePosition();
                        Vec3 vec31 = target.getEyePosition();
                        ModNetwork.sendToALL(new SLightningPacket(vec3, vec31, 5));
                    }

                    harmed.add(target);
                    prevTarget = target;
                }
            }
        }
    }

