public void damageEntities() {
        double actualRadius = this.radius() * 2.0D;
        List<Entity> list1 = this.level.getEntities(this, new AABB(this.getX() - actualRadius, this.getY() - actualRadius, this.getZ() - actualRadius, this.getX() + actualRadius, this.getY() + 6.0D + actualRadius, this.getZ() + actualRadius), this::canHitEntity);
        for(Entity entity : list1) {
            if (entity instanceof LivingEntity livingEntity) {
                if (EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(livingEntity)) {
                    boolean flag = false;
                    DamageSource damageSource = this.damageSources().lightningBolt();
                    if (this.getOwner() != null) {
                        if (!MobUtil.areAllies(this.getOwner(), livingEntity)) {
                            flag = true;
                            damageSource = ModDamageSource.lightning(this, this.getOwner());
                        }
                    } else {
                        flag = true;
                    }
                    if (flag) {
                        if (livingEntity.hurt(damageSource, this.getDamage())){
                            this.hurtEffect(livingEntity);
                        }
                    }
                }
            }
        }
        this.playSound(ModSounds.THUNDER_STRIKE_FAST.get());
    }

public static void playBossMusic(Animation_Monsters entity) {
        if (!CMClientConfig.BossMusic) return;
        SoundEvent soundEvent = entity.getBossMusic();
        if (soundEvent != null && entity.isAlive()) {
            Player player = Minecraft.getInstance().player;
            if (bossMusic != null) {
                float f2 = Minecraft.getInstance().options.getSoundSourceVolume(SoundSource.RECORDS);
                if (f2 <= 0) {
                    bossMusic = null;
                }
                else if (bossMusic.getBoss() == entity && !entity.canPlayerHearMusic(player)) {
                    bossMusic.setBoss(null);
                }
                else if (bossMusic.getBoss() == null && bossMusic.getSoundEvent() == soundEvent) {
                    bossMusic.setBoss(entity);
                }
            } else {
                if (entity.canPlayerHearMusic(player)) {
                    bossMusic = new BossMusicSound(entity.getBossMusic(), entity);
                }
            }
            if (bossMusic != null && !Minecraft.getInstance().getSoundManager().isActive(bossMusic)) {
                Minecraft.getInstance().getSoundManager().play(bossMusic);
            }
        }
    }

