public static boolean hurtNoInvulnerableTime(Entity target, @Nullable LivingEntity living, DamageSource source, float damage) {
    // store last damage before secondary attack
    float oldLastDamage = living == null ? 0 : living.lastHurt;

    // set hurt resistance time to 0 because we always want to deal damage in traits
    int lastInvulnerableTime = target.invulnerableTime;
    target.invulnerableTime = 0;
    boolean hit = target.hurt(source, damage);
    // reset to the old time so bows work right
    target.invulnerableTime = lastInvulnerableTime;
    // set total received damage, important for AI and stuff
    if (living != null) {
      living.lastHurt += oldLastDamage;
    }
    return hit;
  }

protected void checkAndPerformAttack(ToyBase target) {
        long currentTime = dino.level.getGameTime();
        if (Util.canReachPrey(dino, target)) {
            if (currentTime > attackEndTick + 20) {
                ServerAnimationInfo animation = dino.startAttack();
                attackDamageTick = (long) (currentTime + animation.actionDelay);
                attackEndTick = (long) (currentTime + animation.animation.animationLength);
                if (attackDamageTick > attackEndTick) attackDamageTick = attackEndTick;
                dino.getNavigation().stop();
            }
            if (attackDamageTick > 0 && currentTime == attackDamageTick) {
                target.hurt(DamageSource.mobAttack(dino), 0);
                attackDamageTick = -1;
            }
        }
    }

@Override
    protected void doTick(ServerLevel level, LivingEntity entity) {
        Brain<?> brain = entity.getBrain();
        HurtByEntities hurtBy = brain.getMemory(ModMemoryTypes.HURT_BY_ENTITIES.get()).orElseGet(HurtByEntities::empty);
        List<HurtByEntities.HurtBy> remove = hurtBy.hurtBy().stream().filter(x -> x.time() + x.keepInMemoryTicks() > level.getGameTime()).toList();
        if (remove.isEmpty()) return;

        ArrayList<HurtByEntities.HurtBy> newHurts = new ArrayList<>(hurtBy.hurtBy());
        newHurts.removeAll(remove);

        if (newHurts.isEmpty()) {
            brain.eraseMemory(ModMemoryTypes.HURT_BY_ENTITIES.get());
        } else {
            brain.setMemory(ModMemoryTypes.HURT_BY_ENTITIES.get(), new HurtByEntities(newHurts));
        }
    }

