		if (structureStart == null)
			return;

		AoAScheduler.schedule(100, tick -> {
			boolean spawnBoss = false;
			Entity entity = entityType.create(level);
			SoundBuilder soundBuilder = entity instanceof AoABoss boss && boss.getMusic() != null ? SoundBuilder.asMusic(boss.getMusic(), level) : null;

			if (entity != null)
				entity.discard();

			for (Player player : players) {
				if (!(player instanceof ServerPlayer serverPlayer))
					continue;

				if (playerStillValid.test(serverPlayer)) {
					Vec3 pos = RandomUtil.selection(this.playerSpawnPoints);
					spawnBoss = true;

					serverPlayer.connection.teleport(pos.x, pos.y, pos.z, 0, 0);
					InventoryUtil.giveItemTo(serverPlayer, AoAItems.RETURN_CRYSTAL);
					serverPlayer.sendSystemMessage(LocaleUtil.getLocaleMessage(LocaleUtil.createFeedbackLocaleKey("nowhere.boss.bossWarning"), ChatFormatting.GREEN));
				}
				else {
					serverPlayer.sendSystemMessage(LocaleUtil.getLocaleMessage(LocaleUtil.createFeedbackLocaleKey("nowhere.boss.tooFar"), ChatFormatting.RED));
				}

				if (soundBuilder != null)
					soundBuilder.onlyFor(player);
			}

			if (spawnBoss) {
				AABB bounds = getStructureBounds(level);

				AoAScheduler.schedule(1, tick2 -> {
					getEntitiesInside(level, bounds).forEach(entity2 -> {
						if (!(entity2 instanceof Player) && !(entity2 instanceof ItemEntity))
							entity2.discard();
					});
				});

				AoAScheduler.schedule(40, tick2 -> {
					if (soundBuilder != null)
						soundBuilder.play();
				});

				AoAScheduler.schedule(140, tick2 -> {
					int playerCount = getPlayersInside(level, bounds).size();

					if (playerCount > 0)
						bossFunction.spawn(level, getRandomBossSpawn(), stack, playerCount);
				});
			}
		});

		for (Player player : players) {
			player.sendSystemMessage(LocaleUtil.getLocaleMessage(LocaleUtil.createFeedbackLocaleKey("nowhere.boss.teleportWarning"), ChatFormatting.GOLD));
		}
	}

public static boolean performImpacts(World world, LivingEntity caster, @Nullable Entity target, Entity aoeSource,
                                         RegistryEntry<Spell> spellEntry, List<Spell.Impact> impacts, ImpactContext context,
                                         boolean additionalTargetLookup, @Nullable Spell.Impact.Action.Type filteredAction) {
        var trackers = target != null ? Platform.tracking(target) : null;
        SpellTarget.Intent selectedIntent = null;

        var extendedImpacts = SpellModifiers.extendedImpactsOf(caster, spellEntry);
        var area_impact = extendedImpacts.areaImpact();
        var mutableImpacts = extendedImpacts.impacts();

        var perform = true;
        if (additionalTargetLookup && area_impact != null && area_impact.force_indirect) {
            perform = false;
        }

        EnumSet<Spell.Impact.Action.Type> performedActionTypes = EnumSet.noneOf(Spell.Impact.Action.Type.class);
        if (perform) {
            for (var impact : mutableImpacts) {
                var intent = SpellIntents.impactIntent(impact.action);
                if (!impact.action.apply_to_caster // Only filtering for cases when another entity is actually targeted
                        && (selectedIntent != null && selectedIntent != intent)) {
                    // Filter out mixed intents
                    // So dual intent spells either damage or heal, and not do both
                    continue;
                }
                if (filteredAction != null && impact.action.type != filteredAction) {
                    // Filter out actions that are not of the specified type
                    continue;
                }
                if (additionalTargetLookup && !impact.action.allow_on_center_target) {
                    // Skip center target if additional target lookup is enabled
                    continue;
                }

                if (target != null) {
                    var result = performImpact(world, caster, target, spellEntry, impact, context, trackers);
                    if (result) {
                        performedActionTypes.add(impact.action.type);
                        if (!impact.action.apply_to_caster) {
                            // Caster-only impacts hit the caster, not the shared AOE targets, so they
                            // must not define the intent that gates subsequent target impacts (mirrors
                            // the apply_to_caster exemption in the mixed-intent filter above). Otherwise
                            // e.g. a self-buff would cancel the damage dealt to everyone else.
                            selectedIntent = intent;
                        }
                    }
                }
            }
        }

        if (area_impact != null
                && additionalTargetLookup
                && (shouldApplyAreaImpact(area_impact, performedActionTypes) || target == null) ) {
            var exclude = area_impact.force_indirect ? null : target;
            lookupAndPerformAreaImpact(area_impact, spellEntry, caster, exclude, aoeSource, impacts, context, false);
            if (caster instanceof PlayerEntity player) {
                ((WorldScheduler)world).schedule(0, () -> {
                    var location = target != null ? target.getPos() : context.position();
                    SpellTriggers.onSpellAreaImpact(player, target, location, spellEntry);
                });
            }
        }

        var anyPerformed = !performedActionTypes.isEmpty();
        if (anyPerformed && caster instanceof PlayerEntity player) {
            ((WorldScheduler)world).schedule(0, () -> {
                SpellTriggers.onSpellImpactAny(player, target, aoeSource, spellEntry);
            });
        }

        return anyPerformed;
    }

public static boolean deliver(World world, RegistryEntry<Spell> spellEntry, LivingEntity caster, List<DeliveryTarget> targets, ImpactContext context,
                                  @Nullable Vec3d targetLocation, @Nullable Consumer<DeliveryCompletion> completion, boolean forceSuccess, boolean scheduled) {
        var spell = spellEntry.value();

        if (spell.deliver.delay > 0) {
            if (scheduled) {
                Predicate<Entity> validator = (entity) -> !(entity == null || entity.isRemoved());
                if (!validator.test(caster)) {
                    return false;
                }
                targets = targets.stream().filter(target -> validator.test(target.entity())).toList();
            } else {
                List<DeliveryTarget> finalTargets = targets;
                ((WorldScheduler) world).schedule(spell.deliver.delay, () -> deliver(world, spellEntry, caster, finalTargets, context, targetLocation, completion, forceSuccess, true));
                return true;
            }
        }

        var delivered = false;
        switch (spell.deliver.type) {
            case DIRECT -> {
                var anySuccess = false;
                var casterPos = caster.getPos().add(0, caster.getHeight() / 2F, 0);
                if (targets.isEmpty() && targetLocation != null
                        && spell.area_impact != null) { // Special check to allow area impacts only, in the absence of targets
                    var position = targetLocation.lerp(casterPos, 0.001F);
                    var targetSpecificContext = context.position(position);
                    SpellImpacts.performImpacts(world, caster, caster, null, spellEntry, spell.impacts, targetSpecificContext);
                    anySuccess = true; // The area impact will be executed, hence always true
                } else {
                    for(var targeted: targets) {
                        var target = targeted.entity();
                        var position = target == caster
                                ? casterPos
                                : target.getPos().add(0, target.getHeight() / 2F, 0).lerp(casterPos, 0.01F);
                        var targetSpecificContext = targeted.context().position(position);
                        var result = SpellImpacts.performImpacts(world, caster, target, target, spellEntry, spell.impacts, targetSpecificContext);
                        anySuccess = anySuccess || result;
                    }
                }
                delivered = anySuccess;
            }
            case PROJECTILE -> {
                if (targets.isEmpty()) {
                    ProjectileLauncher.shootProjectile(world, caster, null, spellEntry, context);
                } else {
                    for(var targeted: targets) {
                        var target = targeted.entity();
                        var targetSpecificContext = targeted.context();
                        ProjectileLauncher.shootProjectile(world, caster, target, spellEntry, targetSpecificContext);
                    }
                }
                delivered = true;
            }
            case METEOR -> {
                var anyLaunched = false;
                if (targets.isEmpty() && targetLocation != null) {
                    ProjectileLauncher.fallProjectile(world, caster, null, targetLocation, spellEntry, context);
                    anyLaunched = true;
                } else {
                    for(var targeted: targets) {
                        var target = targeted.entity();
                        var targetSpecificContext = targeted.context();
                        ProjectileLauncher.fallProjectile(world, caster, target, null, spellEntry, targetSpecificContext);
                        anyLaunched = true;
                    }
                }
                delivered = anyLaunched;
            }
            case CLOUD -> {
                var placedAny = false;
                if (targets.isEmpty() && targetLocation != null) {
                    CloudPlacer.placeCloud(world, caster, null, targetLocation, spellEntry, context.position(targetLocation));
                    placedAny = true;
                } else {
                    for(var targeted: targets) {
                        var target = targeted.entity();
                        var targetSpecificContext = targeted.context();
                        CloudPlacer.placeCloud(world, caster, target, null, spellEntry, targetSpecificContext);
                        placedAny = true;
                    }
                }
                delivered = placedAny;
            }
            case SHOOT_ARROW -> {
                ArrowHelper.shootArrow(world, caster, spellEntry, context);
                delivered = true;
            }
            case AFFECT_ARROW -> {
                if (caster instanceof SpellCaster.Player shooter) {
                    var arrowContext = shooter.getArrowShootContext();
                    arrowContext.activeSpells.add(spellEntry);
                }
                delivered = true;
            }
            case MELEE -> {
                if (spell.deliver.melee != null
                        && !spell.deliver.melee.attacks.isEmpty()) {
                    var attackers = !targets.isEmpty()
                            ? targets.stream().map(e -> e.entity()).toList()
                            : List.of(caster);
                    var meleeData = spell.deliver.melee;
                    var spellId = spellEntry.getKey().get().getValue();
                    var attacks = meleeData.attacks;
                    if (context.isChanneled()) {
                        var index = context.channelTickIndex() % attacks.size();
                        attacks = List.of(attacks.get(index));
                    }
                    for (var attacker: attackers) {
                        if (!attacker.isOnGround() && !spell.deliver.melee.allow_airborne) {
                            break;
                        }
                        if (attacker instanceof ServerPlayerEntity serverPlayer) {
                            // Map to resolved MeleeAttack structures
                            var meleeAttacks = Melee.createMeleeAttacks(serverPlayer, attacks, spellEntry,
                                    context.charge(), context.chargeModifier());
                            // Send AttackAvailable packet to client
                            var packet = new Packets.AttackAvailable(spellId, meleeAttacks);
                            Platform.util().networkS2C_Send(serverPlayer, packet);
                            delivered = true;
                        }
                    }
                }
            }
            case STASH_EFFECT -> {
                var anyAdded = false;
                var stash = spell.deliver.stash_effect;
                var id = Identifier.of(stash.id);
                var effect = Registries.STATUS_EFFECT.getEntry(id).get();

                var amplifier = stash.amplifier;
                if (stash.amplifier_power_multiplier != 0) {
                    var power = SpellPower.getSpellPower(spell.school, caster);
                    amplifier += (int)(stash.amplifier_power_multiplier * power.nonCriticalValue());
                }
                for (var modifier: SpellModifiers.of(caster, spellEntry, context.chargeModifier())) {
                    amplifier += modifier.stash_amplifier_add;
                }
                for (var targeted: targets) {
                    if (targeted.entity() instanceof LivingEntity livingEntity) {
                        if (stash.stacking) {
                            var stack = -1;
                            var existingInstance = livingEntity.getStatusEffect(effect);
                            if (existingInstance != null) {
                                stack = existingInstance.getAmplifier();
                                livingEntity.removeStatusEffect(effect);
                            }
                            stack += 1;
                            var instance = new StatusEffectInstance(effect, (int) (stash.duration * 20), Math.min(stack, amplifier), false, stash.show_particles, true);
                            livingEntity.addStatusEffect(instance);
                        } else {
                            var instance = new StatusEffectInstance(effect, (int) (stash.duration * 20), amplifier, false, stash.show_particles, true);
                            livingEntity.addStatusEffect(instance);
                        }
                        anyAdded = true;
                    }
                }
                delivered = anyAdded;
            }
            case CUSTOM -> {
                if (spell.deliver.custom != null) {
                    var handler = SpellHandlers.customDelivery.get(spell.deliver.custom.handler);
                    if (handler != null) {
                        delivered = handler.onSpellDelivery(world, spellEntry, caster, targets, context, targetLocation);
                    }
                }
            }
        }

        if (completion != null) {
            completion.accept(new DeliveryCompletion(delivered || forceSuccess));
        }

        return delivered;
    }

@Override
	public boolean causeFallDamage(double dist, float multiplier, DamageSource source) {

		int realDist = Mth.ceil(dist - 5.0F);
		if (realDist >= 0) {
			float dmg = (float) Math.min(Mth.floor((float) realDist * this.damagePerDifficulty[this.level().getDifficulty().getId()]), this.fallDamageMax);
			this.level().getEntities(this, this.getBoundingBox().inflate(1.0F, 0.0F, 1.0F), EntitySelector.NO_SPECTATORS).forEach((entity) -> {
				if (!(entity instanceof AlphaYeti)) {
					entity.hurt(TFDamageTypes.getDamageSource(this.level(), TFDamageTypes.FALLING_ICE), dmg);
				}
			});
		}

		//TF: Shattering particles and sound
		for (int i = 0; i < 200; i++) {
			double dx = this.getX() + 3.0F * (this.random.nextFloat() - this.random.nextFloat());
			double dy = this.getY() + 5.0F * (this.random.nextFloat() - this.random.nextFloat());
			double dz = this.getZ() + 3.0F * (this.random.nextFloat() - this.random.nextFloat());

			this.level().addParticle(new BlockParticleOption(ParticleTypes.BLOCK, this.blockState), dx, dy, dz, 0, 0, 0);
		}

		this.playSound(Blocks.PACKED_ICE.defaultBlockState().getSoundType().getBreakSound(), 3.0F, 0.5F);
		return false;
	}

protected void explode(Vec3 position) {
		int count = 0;
		Entity shooter = getShooter();

		for (LivingEntity target : EntityRetrievalUtil.getEntities(this, 7, LivingEntity.class, target -> EntityUtil.areProbablyEnemies(target, shooter))) {
			if (DamageUtil.doMiscMagicAttack(shooter, target, getShotContext().damage(), position)) {
				HellfireProjectileEntity tail = new HellfireProjectileEntity(this, target.getX(), target.getY(), target.getZ());

				tail.setOwner(shooter);

				level().addFreshEntity(tail);
				target.igniteForSeconds(10);

				if (shooter != null)
					target.hurt(level().damageSources().indirectMagic(shooter, this), 0.1f);

				count++;
			}
		}

		level().playSound(null, getX(), getY(), getZ(), AoASounds.HELLFIRE_IMPACT.get(), getShooter() != null ? getShooter().getSoundSource() : SoundSource.PLAYERS, 1, 1);

		if (count >= 20 && shooter instanceof ServerPlayer)
			AdvancementUtil.grantCriterion((ServerPlayer)shooter, AdventOfAscension.id("overworld/heckfire"), "20_target_hellfire");
	}

@Override
    public InteractionResultHolder<ItemStack> use(Level level, Player player, InteractionHand pUsedHand) {
        if (!level.isClientSide) {
            var pos = getPosition(player.getEyePosition(), 0.425f, .275f, 0.1775f, player.getRotationVector());
            MagicManager.spawnParticles(level, ParticleTypes.CAMPFIRE_COSY_SMOKE, pos.x, pos.y, pos.z, 5, .1, .1, .1, 0.01, false);
            level.playSound(null, player.blockPosition(), SoundEvents.FIREWORK_ROCKET_BLAST, SoundSource.PLAYERS, 4, 1.5f);
            level.playSound(null, player.blockPosition(), SoundEvents.FIREWORK_ROCKET_BLAST_FAR, SoundSource.PLAYERS, 6, 1.5f);
            var hit = RaycastBuilder.begin(level, player)
                    .range(64f)
                    .checkForBlocks(true)
                    .bbInflation(0.1f)
                    .build();
            if (hit instanceof BlockHitResult blockHitResult) {
                var loc = blockHitResult.getLocation();
                MagicManager.spawnParticles(level, new BlockParticleOption(ParticleTypes.BLOCK, level.getBlockState(blockHitResult.getBlockPos())), loc.x, loc.y, loc.z, 25, .1, .1, .1, 0.25, true);
            } else if (hit instanceof EntityHitResult entityHitResult) {
                entityHitResult.getEntity().hurt(level.damageSources().magic(), (float) (10f * player.getAttributeValue(AttributeRegistry.SPELL_POWER)));
                var loc = entityHitResult.getLocation();
                MagicManager.spawnParticles(level, ParticleHelper.BLOOD, loc.x, loc.y, loc.z, 25, .1, .1, .1, 0.25, true);
            }
            CameraShakeManager.addCameraShake(new CameraShakeData(level, 10, player.position(), 5));
            ((ServerPlayer) player).teleportTo((ServerLevel) level, player.getX(), player.getY(), player.getZ(), player.getYRot(), player.getXRot() - Utils.random.nextIntBetweenInclusive(6, 9));
        }
        return super.use(level, player, pUsedHand);
    }

@Override
    public boolean doHurtTarget(Entity target) {
        boolean shouldHurt;
        float damage = (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE);
        float knockback = (float) this.getAttributeValue(Attributes.ATTACK_KNOCKBACK);
        if (target instanceof LivingEntity livingEntity) {
            damage += livingEntity.getMobType().equals(MobType.ARTHROPOD) ? damage : 0;
            knockback += (float) EnchantmentHelper.getKnockbackBonus(this);
        }
        if (shouldHurt = target.hurt(this.damageSources().mobAttack(this), damage)) {
            if (knockback > 0.0f && target instanceof LivingEntity) {
                ((LivingEntity) target).knockback(knockback * 0.5f, Mth.sin(this.getYRot() * ((float) Math.PI / 180)), -Mth.cos(this.getYRot() * ((float) Math.PI / 180)));
                this.setDeltaMovement(this.getDeltaMovement().multiply(0.6, 1.0, 0.6));
            }
            this.doEnchantDamageEffects(this, target);
            this.setLastHurtMob(target);
        }
        if (shouldHurt && target instanceof LivingEntity livingEntity) {
            this.playSound(UPSounds.BEELZE_ATTACK.get(), 0.1F, 1.0F);
            if (random.nextInt(15) == 0 && this.getTarget() instanceof LivingEntity) {
                this.spawnAtLocation(UPItems.BEELZ_SALIVA.get());
            }
        }
        return shouldHurt;
    }

@Override
    protected void onHit(HitResult result) {
        Entity thrower = getOwner();
        if (result.getType() == HitResult.Type.ENTITY) {
            ((EntityHitResult) result).getEntity().hurt(DamageSource.thrown(this, thrower), 0.0F);
        }

        if (!this.level.isClientSide) {
            float wormSize = 0.25F + (float) (Math.random() * 0.35F);

            EntityDeathWorm deathworm = new EntityDeathWorm(IafEntityRegistry.DEATH_WORM.get(), this.level);
            deathworm.setVariant(random.nextInt(3));
            deathworm.setTame(true);
            deathworm.setWormHome(blockPosition());
            deathworm.setWormAge(1);
            deathworm.setDeathWormScale(giant ? (wormSize * 4) : wormSize);
            deathworm.moveTo(this.getX(), this.getY(), this.getZ(), this.getYRot(), 0.0F);
            if (thrower instanceof Player) {
                deathworm.setOwnerUUID(thrower.getUUID());
            }
            this.level.addFreshEntity(deathworm);

            this.level.broadcastEntityEvent(this, (byte) 3);
            this.remove(RemovalReason.DISCARDED);
        }
    }

@Override
    public void tick() {
        Vec3 min = new Vec3(this.slider.getBoundingBox().minX - 0.1, this.slider.getBoundingBox().minY - 0.1, this.slider.getBoundingBox().minZ - 0.1);
        Vec3 max = new Vec3(this.slider.getBoundingBox().maxX + 0.1, this.slider.getBoundingBox().maxY + 0.1, this.slider.getBoundingBox().maxZ + 0.1);
        AABB collisionBounds = new AABB(min, max);
        for (Entity entity : this.slider.level().getEntities(this.slider, collisionBounds)) {
            if (entity instanceof LivingEntity livingEntity && entity.hurt(AetherDamageTypes.entityDamageSource(this.slider.level(), AetherDamageTypes.CRUSH, this.slider), 6)) {
                if (livingEntity instanceof Player player && player.getUseItem().is(Items.SHIELD) && player.isBlocking()) { // Disables the player's Shield if one is being used.
                    player.getCooldowns().addCooldown(Items.SHIELD, 100);
                    player.stopUsingItem();
                    this.slider.level().broadcastEntityEvent(player, (byte) 30);
                }
                entity.setDeltaMovement(entity.getDeltaMovement().multiply(4.0, 1.0, 4.0).add(0.0, 0.25, 0.0));

                this.slider.setMoveDelay(this.slider.calculateMoveDelay());
                this.slider.setAttackCooldown(20);
                this.slider.setMoveDirection(null);

                // Stop the Slider's movement.
                this.slider.playSound(this.slider.getCollideSound(), 2.5F, 1.0F / (this.slider.getRandom().nextFloat() * 0.2F + 0.9F));
                this.slider.setDeltaMovement(Vec3.ZERO);
            } else if (!(entity instanceof Player player && player.isCreative()) && !(entity instanceof Slider)) {
                entity.setDeltaMovement(this.slider.getDeltaMovement().multiply(4.0, 1.0, 4.0).add(0.0, 0.25, 0.0));
            }
        }
    }

@Override
	public boolean hurt(DamageSource source, float amount) {
		if (source == DamageSource.OUT_OF_WORLD) {
			remove();

			return true;
		}

		if (!level.isClientSide && isAlive() && source.getDirectEntity() instanceof PlayerEntity) {
			TreeSpiritEntity treeSpirit = new TreeSpiritEntity(AoAEntities.Mobs.TREE_SPIRIT.get(), level);

			treeSpirit.moveTo(getX(), getY(), getZ(), yRot, xRot);
			level.addFreshEntity(treeSpirit);
			treeSpirit.hurt(source, amount);

			if (treeSpirit.getHealth() <= 0)
				AdvancementUtil.completeAdvancement((ServerPlayerEntity)source.getDirectEntity(), new ResourceLocation("aoa3", "overworld/mightiest_tree_in_the_forest"), "tree_spirit_instakill");

			level.playSound(null, getX(), getY(), getZ(), AoASounds.ENTITY_TREE_SPIRIT_AMBIENT.get(), SoundCategory.HOSTILE, 1.0f, 1.0f);
			remove();

			return true;
		}

		return false;
	}

@Override
    public boolean hurt(DamageSource source, float damage) {
        if (this.getAnimation() == GUARDIAN_MASS_DESTRUCTION && !source.is(DamageTypeTags.BYPASSES_INVULNERABILITY)) {
            return false;
        }
        Entity entity = source.getDirectEntity();
        if (!this.getIsHelmetless()) {
            if (entity instanceof AbstractArrow) {
                return false;
            }
        }
        if (entity instanceof ShulkerBullet || entity instanceof Ender_Guardian_Bullet_Entity) {
            return false;
        }
        if (entity instanceof AbstractGolem) {
            damage *= 0.5;
        }

        boolean attack = super.hurt(source, damage);
        if(attack) {
            if (this.getIsHelmetless()) {
                this.playSound(SoundEvents.SHULKER_HURT, 1.0f, 0.8f);
            }
        }
        return attack;
    }

public void tick() {
            if(vulture.isFlying()){
                vulture.setTackling(true);
            }else{
                vulture.setTackling(false);
            }
            if (vulture.getTarget() != null) {
                this.vulture.getMoveControl().setWantedPosition(vulture.getTarget().getX(), vulture.getTarget().getY() + vulture.getTarget().getEyeHeight(), vulture.getTarget().getZ(), 2.0D);
                final double d0 = this.vulture.getX() - this.vulture.getTarget().getX();
                final double d2 = this.vulture.getZ() - this.vulture.getTarget().getZ();
                final float f = (float)(Mth.atan2(d2, d0) * (double)Mth.RAD_TO_DEG) - 90.0F;
                vulture.setYRot(f);
                vulture.yBodyRot = vulture.getYRot();
                if (vulture.getBoundingBox().inflate(0.3F, 0.3F, 0.3F).intersects(vulture.getTarget().getBoundingBox()) && vulture.tackleCooldown == 0) {
                    tackleCooldown = 100 + random.nextInt(200);
                    float dmg = (float) vulture.getAttribute(Attributes.ATTACK_DAMAGE).getValue();
                    if(vulture.getTarget().hurt(vulture.damageSources().mobAttack(vulture), dmg)){
                        if(vulture.getHealth() < vulture.getMaxHealth() - dmg && vulture.getSoulLevel() < 5){
                            this.vulture.setSoulLevel(vulture.getSoulLevel() + 1);
                            this.vulture.heal(dmg);
                            this.vulture.level().broadcastEntityEvent(vulture, (byte)68);
                        }
                    }
                    stop();
                }
            }
        }

@Override
	protected void onImpact(RayTraceResult rayTrace){

		Entity entityHit = rayTrace.entityHit;

		if(entityHit != null){

			float damage = Spells.homing_spark.getProperty(Spell.DAMAGE).floatValue() * damageMultiplier;
			entityHit.attackEntityFrom(MagicDamage.causeIndirectMagicDamage(this, this.getThrower(),
					DamageType.SHOCK), damage);

		}

		this.playSound(WizardrySounds.ENTITY_HOMING_SPARK_HIT, 1.0F, 1.2F / (this.rand.nextFloat() * 0.2F + 0.9F));

		// Particle effect
		if(world.isRemote){
			for(int i = 0; i < 8; i++){
				double x = this.posX + rand.nextDouble() - 0.5;
				double y = this.posY + this.height / 2 + rand.nextDouble() - 0.5;
				double z = this.posZ + rand.nextDouble() - 0.5;
				ParticleBuilder.create(Type.SPARK).pos(x, y, z).spawn(world);
			}
		}

		this.setDead();
	}

@Override
	protected void onHitEntity(EntityHitResult p_37573_) {
		Entity entity = p_37573_.getEntity();
		Entity entity1 = this.getController();
		DamageSource damagesource = CMDamageTypes.causeStormBringerDamage(this, (Entity)(entity1 == null ? this : entity1));
		if (entity.hurt(damagesource, (float) this.getBaseDamage())) {

			if (entity.getType() == EntityType.ENDERMAN) {
				return;
			}

			if (entity instanceof LivingEntity livingentity) {
				this.doKnockback(livingentity, damagesource);
				this.doPostHurtEffects(livingentity);
				this.playSound(this.getHitGroundSoundEvent(), 1.0F, 1.2F / (this.random.nextFloat() * 0.2F + 0.9F));
			}
			if(!this.getHookMode()) {
				if (this.getPassengers().isEmpty()) {
					if (!this.level().isClientSide) {
						entity.startRiding(this, true);
						Cataclysm.NETWORK_WRAPPER.send(PacketDistributor.TRACKING_ENTITY_AND_SELF.with(() -> entity), new MessageEntityCamera(entity.getId(),false));
					}
				}
			}
		}

	}

public void tick() {
        super.tick();
        prevAttackProgress = attackProgress;
        if (this.entityData.get(ATTACK_TICK) > 0) {
            if(attackProgress == 3){
                this.playSound(AMSoundRegistry.LOBSTER_ATTACK.get(), this.getSoundVolume(), this.getVoicePitch());
            }
            if (this.entityData.get(ATTACK_TICK) == 2 && this.getTarget() != null && this.distanceTo(this.getTarget()) < 1.3D) {
                this.getTarget().hurt(this.damageSources().mobAttack(this), 2);
            }
            this.entityData.set(ATTACK_TICK, this.entityData.get(ATTACK_TICK) - 1);
            if (attackProgress < 5F) {
                attackProgress++;
            }
        } else {
            if (attackProgress > 0F) {
                attackProgress--;
            }
        }
        if(attackCooldown > 0){
            attackCooldown--;
        }
        if(this.getTarget() != null && this.distanceTo(this.getTarget()) <= 1F && attackCooldown == 0){
            this.lookAt(this.getTarget(), 180F, 20F);
            doHurtTarget(this.getTarget());
            attackCooldown = 20;
        }
    }

@Override
    public void onLeftClick(Player player, ItemStack stack) {

        float strength = player.getAttackStrengthScale(0.5F);
        if (strength < 0.9F || player.isSprinting() || player.isSecondaryUseActive() || !hasEnergy(stack, false)) {
            return;
        }
        float damage = (float) player.getAttributeValue(Attributes.ATTACK_DAMAGE) * (0.2F + strength * strength * 0.8F);
        float sweep = EnchantmentHelper.getSweepingDamageRatio(player);
        boolean empowered = isEmpowered(stack);
        boolean hit = false;
        for (LivingEntity target : player.level.getEntitiesOfClass(LivingEntity.class, stack.getSweepHitBox(player, player))) {
            if (target == player || player.isAlliedTo(target) || (empowered && target.isBaby()) ||
                    (target instanceof ArmorStand stand && stand.isMarker()) || !player.canReach(target, 0)) {
                continue;
            }
            hit = true;
            Vec3 disp = player.position().subtract(target.position());
            target.knockback(0.3F, disp.x, disp.z);
            float bonus = EnchantmentHelper.getDamageBonus(stack, target.getMobType()) * strength;
            target.hurt(player.level.damageSources().playerAttack(player), 1.0F + (damage + bonus) * sweep);
        }
        if (hit) {
            useEnergy(stack, false, player);
        }
        player.level.playSound(null, player.getX(), player.getY(), player.getZ(), SoundEvents.PLAYER_ATTACK_SWEEP, player.getSoundSource(), 1.0F, 1.0F);
        player.sweepAttack();
    }

@Override
	public void onUpdate(){

		super.onUpdate();
		// Undoes the despawning on peaceful behaviour. I don't think there's anything in super.onUpdate that sets
		// isDead other than that, but it's better to do a quick sanity check just to be sure.
		if(this.isDead && world.getDifficulty() == EnumDifficulty.PEACEFUL && this.getHealth() > 0) this.isDead = false;
		// Bursts instantly rather than doing the falling over animation.
		if(this.getHealth() <= 0) this.setDead();

		this.updateDelegate();

		// Damages and slows the slime's victim or makes the slime explode if the victim is dead.
		if(this.getRidingEntity() != null && this.getRidingEntity() instanceof EntityLivingBase
				&& ((EntityLivingBase)this.getRidingEntity()).getHealth() > 0){
			if(this.ticksExisted % 16 == 1){
				this.getRidingEntity().attackEntityFrom(DamageSource.MAGIC, 1);
				if(this.getRidingEntity() != null && !this.world.isRemote){ // Some mobs force-dismount when attacked (normally when dying)
					((EntityLivingBase)this.getRidingEntity())
							.addPotionEffect(new PotionEffect(MobEffects.SLOWNESS, 20, 2));
				}
				this.playSound(WizardrySounds.ENTITY_MAGIC_SLIME_ATTACK, 1.0f, 1.0f);
				this.squishAmount = 0.5F;
			}
		}else{
			this.setDead();
		}
	}

@Override
    protected void onImpact(RayTraceResult result) {
        double damage = this.size / 50.0 * this.damagingness;
        switch (result.typeOfHit) {
            case ENTITY:
                if (result.entityHit != null && result.entityHit != shootingEntity) {
                    result.entityHit.attackEntityFrom(DamageSource.causeThrownDamage(this, this.shootingEntity), (int) damage);
                }
                break;
            case BLOCK:
                break;
            default:
                break;
        }
        if (FMLCommonHandler.instance().getEffectiveSide() == Side.SERVER) {
            boolean flag = this.worldObj.getGameRules().getBoolean("mobGriefing");
            this.worldObj.createExplosion(this, this.posX, this.posY, this.posZ, (float) (this.size / 50.0f * 3 * this.explosiveness), flag);
        }
        for (int var3 = 0; var3 < 8; ++var3) {
            this.worldObj.spawnParticle(EnumParticleTypes.FLAME,
                    this.posX + Math.random() * 0.1, this.posY + Math.random() * 0.1, this.posZ + Math.random() * 0.1,
                    0.0D, 0.0D, 0.0D);
        }

        if (FMLCommonHandler.instance().getEffectiveSide() == Side.SERVER) {
            this.setDead();
        }
    }

@Override
	protected void onHit(HitResult result) {
		for (int var3 = 0; var3 < 8; ++var3) {
			level().addParticle(ParticleTypes.ITEM_SNOWBALL, getX(), getY(), getZ(), 0.0D, 0.0D, 0.0D);
		}

		if (!level().isClientSide) {
			if (result.getType() == HitResult.Type.ENTITY) {
				Entity entityHit = ((EntityHitResult) result).getEntity();
				int damage = getSnowballDamage();
				if (entityHit.fireImmune()) {
					damage += getSnowballDamageFireImmuneBonus();
				}
				if (entityHit instanceof Blaze) {
					damage += getSnowballDamageBlazeBonus();
				}
				entityHit.hurt(damageSources().thrown(this, getOwner()), damage);
			} else if (result.getType() == HitResult.Type.BLOCK) {
				BlockPos posUp = ((BlockHitResult) result).getBlockPos().above();
				if (level().getBlockState(posUp).getBlock() instanceof BaseFireBlock) {
					level().playSound(null, posUp, SoundEvents.GENERIC_BURN, SoundSource.NEUTRAL, 0.5F,
							RandHelper.getRandomMinusOneToOne(level().random) * 0.8F);
					level().setBlockAndUpdate(posUp, Blocks.AIR.defaultBlockState());
				}
			}
			discard();
		}
	}

private void delayExhaustion(Player attacker, ItemModularHandheld item, ItemStack itemStack, int duration, int amplifier) {
        int delay = getChargeTime(item, itemStack) + getCooldown(item, itemStack) + item.getEffectLevel(itemStack, ItemEffect.abilityEcho);

        try {
            DelayData data = delayCache.get(attacker.getId(), DelayData::new);
            data.timestamp = attacker.level().getGameTime() + delay;
            data.amplifier += amplifier;
        } catch (ExecutionException e) {
            e.printStackTrace();
        }

        ServerScheduler.schedule(delay + 1, () -> {
            DelayData data = delayCache.getIfPresent(attacker.getId());
            if (attacker.isAlive() && attacker.level() != null && data != null && attacker.level().getGameTime() > data.timestamp) {
                int currentAmp = Optional.ofNullable(attacker.getEffect(ExhaustedPotionEffect.instance))
                        .map(MobEffectInstance::getAmplifier)
                        .orElse(-1);
                attacker.addEffect(new MobEffectInstance(ExhaustedPotionEffect.instance, duration, currentAmp + data.amplifier, false, true));

                delayCache.invalidate(attacker.getId());
            }
        });
    }

private void handleAfterAttacking(LivingDamageEvent.Post ev) {
		if (ev.getNewDamage() > 0 && primedAttack && DamageUtil.isMeleeDamage(ev.getSource()) && !getPlayer().getItemInHand(InteractionHand.OFF_HAND).isEmpty()) {
			this.primedAttack = false;

			if (skill.getPlayerDataManager().getResource(AoAResources.ENERGY.get()).consume(this.energyCost, true)) {
				ServerPlayer player = (ServerPlayer)getPlayer();
				LivingEntity target = ev.getEntity();

				AoAScheduler.schedule(player.getCurrentSwingDuration() - 1, tick -> {
					player.swing(InteractionHand.OFF_HAND, true);

					if (target != null && target.isAlive()) {
						if (player.distanceToSqr(target) < 36 && player.hasLineOfSight(target)) {
							DamageUtil.doScaledKnockback(target, player, 0.3f, 1, 1, 1);
							EntityUtil.applyPotions(target, player, new EffectBuilder(MobEffects.MOVEMENT_SLOWDOWN, this.stunDuration).level(127), new EffectBuilder(MobEffects.DIG_SLOWDOWN, this.stunDuration).level(127));
							activatedActionKey(player);

							if (skill.canGainXp(true))
								PlayerUtil.giveTimeBasedXpToPlayer(player, this.skill.type(), 39,  false);
						}
					}
				});
			}
		}
	}

@Override
    protected void onHitEntity(EntityHitResult result) {
        Entity entity = result.getEntity();
        float f = 12.0F;
        if (entity instanceof LivingEntity) {
            LivingEntity livingentity = (LivingEntity) entity;
            f += EnchantmentHelper.getDamageBonus(this.tridentItem, livingentity.getMobType());
        }

        Entity entity1 = this.getOwner();
        DamageSource damagesource = DamageSource.trident(this, entity1 == null ? this : entity1);
        entitiesHit++;
        if (entitiesHit >= getMaxPiercing())
            this.dealtDamage = true;
        SoundEvent soundevent = SoundEvents.TRIDENT_HIT;
        if (entity.hurt(damagesource, f)) {
            if (entity.getType() == EntityType.ENDERMAN) {
                return;
            }

            if (entity instanceof LivingEntity) {
                LivingEntity livingentity1 = (LivingEntity) entity;
                if (entity1 instanceof LivingEntity) {
                    EnchantmentHelper.doPostHurtEffects(livingentity1, entity1);
                    EnchantmentHelper.doPostDamageEffects((LivingEntity) entity1, livingentity1);
                }

                this.doPostHurtEffects(livingentity1);
            }
        }

        float f1 = 1.0F;
        if (this.level instanceof ServerLevel && this.level.isThundering() && EnchantmentHelper.hasChanneling(this.tridentItem)) {
            BlockPos blockpos = entity.blockPosition();
            if (this.level.canSeeSky(blockpos)) {
                LightningBolt lightningboltentity = EntityType.LIGHTNING_BOLT.create(this.level);
                lightningboltentity.moveTo(Vec3.atCenterOf(blockpos));
                lightningboltentity.setCause(entity1 instanceof ServerPlayer ? (ServerPlayer) entity1 : null);
                this.level.addFreshEntity(lightningboltentity);
                soundevent = SoundEvents.TRIDENT_THUNDER;
                f1 = 5.0F;
            }
        }

        this.playSound(soundevent, f1, 1.0F);
    }

@SubscribeEvent
	public static void onAttackEntityEvent(AttackEntityEvent event){

		ItemStack stack = event.getEntityPlayer().getHeldItemMainhand();

		if(stack.getItem() instanceof ItemLightningHammer && event.getTarget() instanceof EntityLivingBase){

			EntityPlayer wielder = event.getEntityPlayer();
			EntityLivingBase hit = (EntityLivingBase)event.getTarget();

			float attackStrength = wielder.getCooledAttackStrength(0);

			double dx = wielder.posX - hit.posX;
			double dz;
			for(dz = wielder.posZ - hit.posZ; dx * dx + dz * dz < 1.0E-4D; dz = (Math.random() - Math.random())
					* 0.01D){
				dx = (Math.random() - Math.random()) * 0.01D;
			}

			hit.knockBack(wielder, 2 * attackStrength, dx, dz);

			if(attackStrength == 1){ // Only chains when the attack meter is full

				List<EntityLivingBase> nearby = EntityUtils.getLivingWithinRadius(CHAINING_RANGE, hit.posX, hit.posY, hit.posZ, hit.world);

				nearby.remove(hit);
				nearby.remove(wielder);
				// When held, the number of chaining targets is halved
				int maxTargets = Spells.lightning_hammer.getProperty(LightningHammer.SECONDARY_MAX_TARGETS).intValue() / 2;
				while(nearby.size() > maxTargets) nearby.remove(nearby.size() - 1);

				for(EntityLivingBase target : nearby){

					target.attackEntityFrom(MagicDamage.causeDirectMagicDamage(wielder, DamageType.SHOCK), CHAINING_DAMAGE * ((ItemLightningHammer)stack.getItem()).getDamageMultiplier(stack));

					if(hit.world.isRemote){
						ParticleBuilder.create(Type.LIGHTNING).pos(hit.getPositionVector().add(0, hit.height / 2, 0))
								.target(target).spawn(hit.world);
						ParticleBuilder.spawnShockParticles(hit.world, target.posX, target.posY + target.height / 2, target.posZ);
					}

					//target.playSound(WizardrySounds.SPELL_SPARK, 1, 1.5f + 0.4f * world.rand.nextFloat());
				}
			}
		}
	}

@Override
	public boolean cast(World world, EntityPlayer caster, EnumHand hand, int ticksInUse, SpellModifiers modifiers){

		if(caster.onGround){

			List<EntityLivingBase> targets = EntityUtils.getLivingWithinRadius(
					getProperty(EFFECT_RADIUS).floatValue() * modifiers.get(WizardryItems.blast_upgrade),
					caster.posX, caster.posY, caster.posZ, world);

			for(EntityLivingBase target : targets){
				if(AllyDesignationSystem.isValidTarget(caster, target)){
					// Base damage is 4 hearts no matter where the target is.
					target.attackEntityFrom(MagicDamage.causeDirectMagicDamage(caster, DamageType.SHOCK),
							getProperty(DAMAGE).floatValue() * modifiers.get(SpellModifiers.POTENCY));

					if(!world.isRemote){

						double dx = target.posX - caster.posX;
						double dz = target.posZ - caster.posZ;
						// Normalises the velocity.
						double vectorLength = MathHelper.sqrt(dx * dx + dz * dz);
						dx /= vectorLength;
						dz /= vectorLength;

						target.motionX = getProperty(REPULSION_VELOCITY).floatValue() * dx;
						target.motionY = 0;
						target.motionZ = getProperty(REPULSION_VELOCITY).floatValue() * dz;

						// Player motion is handled on that player's client so needs packets
						if(target instanceof EntityPlayerMP){
							((EntityPlayerMP)target).connection.sendPacket(new SPacketEntityVelocity(target));
						}
					}
				}
			}

			if(world.isRemote){
				ParticleBuilder.create(Type.LIGHTNING_PULSE).pos(caster.posX, caster.posY
						+ GeometryUtils.ANTI_Z_FIGHTING_OFFSET, caster.posZ)
				.scale(modifiers.get(WizardryItems.blast_upgrade)).spawn(world);
			}

			this.playSound(world, caster, ticksInUse, -1, modifiers);
			return true;
		}
		return false;
	}

@Override
    public void tick() {
        super.tick();
        if (this.level instanceof ServerLevel serverLevel) {
            float area = this.getAreaOfEffect() / 2;
            float f = 1.5F + area;
            ColorUtil color = ColorUtil.WHITE;
            ServerParticleUtil.windParticle(serverLevel, color, (f - 1.0F) + serverLevel.getRandom().nextFloat() * 0.5F, 0.0F, this.getId(), this.position());
            ServerParticleUtil.windParticle(serverLevel, color, f + serverLevel.getRandom().nextFloat() * 0.5F, 0.0F, this.getId(), this.position());

            if (this.tickCount == 20){
                List<Entity> targets = new ArrayList<>();
                float area0 = 1.0F + area;
                AABB aabb = this.getBoundingBox();
                AABB aabb1 = new AABB(aabb.minX - area0, aabb.minY - 1.0F, aabb.minZ - area0, aabb.maxX + area0, aabb.maxY + 1.0F, aabb.maxZ + area0);
                for (Entity entity : this.level.getEntitiesOfClass(Entity.class, aabb1)){
                    if (this.getOwner() != null) {
                        if (entity != this.getOwner() && !MobUtil.areAllies(entity, this.getOwner())) {
                            targets.add(entity);
                        }
                    } else {
                        targets.add(entity);
                    }
                }
                if (!targets.isEmpty()){
                    for (Entity entity : targets) {
                        if (entity instanceof LivingEntity livingEntity) {
                            livingEntity.hurt(ModDamageSource.windBlast(this, this.getOwner()), this.getDamage());
                            MobUtil.push(livingEntity, 0.0D, 1.0D, 0.0D);
                        } else if (entity instanceof AbstractCyclone cyclone && cyclone.getTrueOwner() != this.getOwner()){
                            cyclone.trueRemove();
                        }
                    }
                }
            }
        }
        if (this.tickCount == 1){
            this.playSound(ModSounds.UPDRAFT_BLAST.get(), 0.9F, 1.5F);
        }
        if (this.tickCount > 20){
            this.setDeltaMovement(this.getDeltaMovement().add(0.0D, 0.25D, 0.0D));
            this.move(MoverType.SELF, this.getDeltaMovement());
        }
        if (this.tickCount % 30 == 0){
            this.discard();
        }
    }

@Override
	public void onUpdate() {
		super.onUpdate();
		if (isAIDisabled()) return;

		if ((ticksExisted % RandUtil.nextInt(100, 200)) == 0)
			playSound(ModSounds.HALLOWED_SPIRIT, RandUtil.nextFloat(), RandUtil.nextFloat());

		fallDistance = 0;

		EntityPlayer farPlayer = world.getNearestPlayerNotCreative(this, 300);
		setAttackTarget(farPlayer);
		if (getAttackTarget() != null) {
			noClip = true;
			Vec3d direction = getPositionVector().subtract(getAttackTarget().getPositionVector()).normalize();
			motionX = direction.x * -0.1;
			motionY = direction.y * -0.1;
			motionZ = direction.z * -0.1;
			rotationYaw = (float) (((-MathHelper.atan2(direction.x, direction.z) * 180) / Math.PI) - 180) / 2;
		} else {
			if (!collidedVertically) {
				motionY = 0;
			}
			noClip = false;
		}

		EntityPlayer player = getAttackTarget() == null ? null : world.getNearestPlayerNotCreative(this, 2);
		EntityPlayer closePlayer = getAttackTarget() == null ? null : world.getNearestPlayerNotCreative(this, 30);
		boolean angry = player != null;

		ClientRunnable.run(new ClientRunnable() {
			@Override
			@SideOnly(Side.CLIENT)
			public void runIfClient() {
				if ((closePlayer != null) && !angry)
					LibParticles.SPIRIT_WIGHT_FLAME_FAR(world, getPositionVector().add(0, getEyeHeight(), 0));
				else if (angry)
					LibParticles.SPIRIT_WIGHT_FLAME_CLOSE(world, getPositionVector().add(0, getEyeHeight(), 0));
				else LibParticles.SPIRIT_WIGHT_FLAME_NORMAL(world, getPositionVector().add(0, getEyeHeight(), 0));
			}
		});

		if (angry) {
			player.attackEntityFrom(DamageSource.MAGIC, 0.15f);
			player.hurtResistantTime = 0;
		}
	}

@Override
	public void onUseTick(Level level, LivingEntity living, ItemStack stack, int count) {
		Cataclysm.PROXY.playWorldSound(living, (byte) 1);

		if (level instanceof ServerLevel serverLevel) {
			double range = 2.5D;
			Vec3 srcVec = living.getEyePosition();
			Vec3 lookVec = living.getViewVector(1.0F);

			Vec3 lookOffset = lookVec.scale(range);
			Vec3 destVec = srcVec.add(lookOffset);

			double padding = 1.0D;
			AABB searchArea = living.getBoundingBox().expandTowards(lookOffset).inflate(padding);
			List<Entity> possibleList = level.getEntities(living, searchArea);
			DamageSource shredderDamage = CMDamageTypes.causeShredderDamage(living);
			float basedmg = AttributeUtils.OriginDamage(living, stack);

			for (Entity entity : possibleList) {
				if (entity instanceof LivingEntity target) {
					double borderSize = 0.5D;
					AABB collisionBB = target.getBoundingBox().inflate(borderSize);
					boolean isHit = collisionBB.contains(srcVec) || collisionBB.clip(srcVec, destVec).isPresent();

					if (isHit) {
						float bonusDamage = EnchantmentHelper.getDamageBonus(stack, target.getMobType());
						float enchanteddmg = basedmg + bonusDamage;

						float finaldmg = enchanteddmg / 8.5F;
						if (target.hurt(shredderDamage, finaldmg)) {
							serverLevel.sendParticles(
									new ParryParticleOptions(255, 106, 0),
									target.getX(),
									target.getY(0.5),
									target.getZ(),
									2,
									target.getDeltaMovement().x,
									target.getDeltaMovement().y,
									target.getDeltaMovement().z,
									(level.getRandom().nextFloat() - 0.5F)
							);
						}
					}
				}
			}
		}
	}

@Override
    public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
        int range = spellStat.getRange();
        float damage = SpellConfig.ThunderboltDamage.get().floatValue() * WandUtil.damageMultiply();
        if (WandUtil.enchantedFocus(caster)) {
            range += WandUtil.getRangeLevel(caster);
            damage += WandUtil.getPotencyLevel(caster);
        }
        ColorUtil colorUtil = new ColorUtil(0xb1abf1);
        if (staff.is(ModItems.NAMELESS_STAFF.get())) {
            colorUtil = new ColorUtil(0xa7fc3e);
        }
        damage += spellStat.getPotency();
        Vec3 vec3 = caster.getEyePosition();
        BlockHitResult rayTraceResult = this.blockResult(worldIn, caster, range);
        Entity target = MobUtil.getNearbyTarget(worldIn, caster, range, 1.0F);
        Optional<BlockPos> lightningRod = BlockFinder.findLightningRod(worldIn, BlockPos.containing(rayTraceResult.getLocation()), range);
        if (lightningRod.isPresent() && !rightStaff(staff)){
            BlockPos blockPos = lightningRod.get();
            ModNetwork.sendToALL(new SThunderBoltPacket(vec3, new Vec3(blockPos.getX(), blockPos.getY(), blockPos.getZ()), colorUtil, 10));
            this.playSound(worldIn, caster, ModSounds.THUNDERBOLT.get());
        } else {
            LivingEntity livingEntity = MobUtil.getLivingTarget(target);
            if (livingEntity != null && ForgeHooks.onLivingAttack(livingEntity, ModDamageSource.directShock(caster), damage)) {
                Vec3 vec31 = new Vec3(livingEntity.getX(), livingEntity.getY() + livingEntity.getBbHeight() / 2, livingEntity.getZ());
                ModNetwork.sendToALL(new SThunderBoltPacket(vec3, vec31, colorUtil, 10));
                if (livingEntity.hurt(ModDamageSource.directShock(caster), damage)){
                    float chance = rightStaff(staff) ? 0.25F : 0.05F;
                    float chainDamage = damage / 2.0F;
                    if (worldIn.isThundering() && worldIn.isRainingAt(livingEntity.blockPosition())){
                        chance += 0.25F;
                        chainDamage = damage;
                    }
                    if (worldIn.random.nextFloat() <= chance){
                        livingEntity.addEffect(new MobEffectInstance(GoetyEffects.SPASMS.get(), MathHelper.secondsToTicks(5)));
                    }
                    if (rightStaff(staff)){
                        WandUtil.chainLightning(livingEntity, caster, range / 4.0D, chainDamage);
                    }
                }
                this.playSound(worldIn, caster, ModSounds.THUNDERBOLT.get());
            } else {
                BlockPos blockPos = rayTraceResult.getBlockPos();
                ModNetwork.sendToALL(new SThunderBoltPacket(vec3, new Vec3(blockPos.getX(), blockPos.getY(), blockPos.getZ()), colorUtil, 10));
                this.playSound(worldIn, caster, ModSounds.THUNDERBOLT.get());
            }
        }
    }

@Override
	public boolean run(@NotNull World world, ModuleInstanceEffect instance, @Nonnull SpellData spell, @Nonnull SpellRing spellRing) {
		Entity targetEntity = spell.getVictim(world);
		Entity caster = spell.getCaster(world);
		BlockPos pos = spell.getTargetPos();

		if (pos == null) return false;

		double potency = spellRing.getAttributeValue(world, AttributeRegistry.POTENCY, spell) / 2;

		if (!spellRing.taxCaster(world, spell, true)) return false;

		if (targetEntity instanceof EntityLivingBase) {

			PotionEffect slowness = ((EntityLivingBase) targetEntity).getActivePotionEffect(MobEffects.SLOWNESS);
			PotionEffect frost = ((EntityLivingBase) targetEntity).getActivePotionEffect(ModPotions.SLIPPERY);
			int mult = 0;
			if (slowness != null)
				mult += slowness.getAmplifier() + 1;
			if (frost != null)
				mult += frost.getAmplifier() + 1;
			potency *= 1 + mult * 0.5;

			int invTime = targetEntity.hurtResistantTime;
			targetEntity.hurtResistantTime = 0;

			world.playSound(null, pos, ModSounds.MARBLE_EXPLOSION, CommonProxy.SoundCategory_WizardryGeneral, 2, RandUtil.nextFloat(0.8f, 1.2f));
			world.playSound(null, pos, ModSounds.FIREWORK, CommonProxy.SoundCategory_WizardryGeneral, 2, RandUtil.nextFloat(0.8f, 1.2f));
			if (caster instanceof EntityLivingBase)
			{
				((EntityLivingBase) caster).setLastAttackedEntity(targetEntity);
				if (caster instanceof EntityPlayer)
					targetEntity.attackEntityFrom(DamageSource.causePlayerDamage((EntityPlayer) caster).setMagicDamage(), (float) potency);
				else
					targetEntity.attackEntityFrom(new DamageSource("generic").setMagicDamage(), (float) potency);
			}
			else
				targetEntity.attackEntityFrom(new DamageSource("generic").setMagicDamage(), (float) potency);

			targetEntity.hurtResistantTime = invTime;
		}

		// TODO: EffectShatter Sound
//		Vec3d target = spell.getTargetWithFallback();
//		if (target != null)
//			world.playSound(null, new BlockPos(target), ModSounds.CHAINY_ZAP, SoundCategory.NEUTRAL, 0.5f, 1f);
		return true;
	}

public void tick() {
        super.tick();
        AnimationHandler.INSTANCE.updateAnimations(this);
        prevangryProgress = angryProgress;
        if (this.isAggressive() && angryProgress < 10F) {
            angryProgress++;
        }
        if (!this.isAggressive() && angryProgress > 0F) {
            angryProgress--;
        }
        LivingEntity target = this.getTarget();
        if(this.isAlive()) {
            if (this.getAnimation() == COBOLETON_ATTACK) {
                if (this.getAnimationTick() == 11) {
                    this.playSound(SoundEvents.PLAYER_ATTACK_SWEEP, 1.0F, 1.0F / (this.getRandom().nextFloat() * 0.4F + 0.8F));
                    if (target != null) {
                        if (this.distanceTo(target) < this.getBbWidth() * 2.5F * this.getBbWidth() * 2.5F + target.getBbWidth()) {
                            float damage = (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE);
                            target.hurt(damageSources().mobAttack(this), damage);

                            ItemStack offhand = target.getOffhandItem();
                            ItemStack mainhand = target.getMainHandItem();
                            Optional<SlotResult> slot = CuriosApi.getCuriosHelper().findFirstCurio(target, stack -> stack.is(ModItems.STICKY_GLOVES.get()));
                            if(this.random.nextFloat() * 100.0F <= (float)CMCommonConfig.Koboleton.CauseKoboletontoDropItemInHandPercent) {
                                if (slot.isEmpty()) {
                                    if (!offhand.isEmpty()) {
                                        if (!offhand.is(ModTag.STICKY_ITEM)) {
                                            int i = offhand.getCount();
                                            this.koboletonstealdrop(offhand.copyWithCount(1), target);
                                            target.setItemSlot(EquipmentSlot.OFFHAND, offhand.split(i - 1));
                                        }
                                    } else {
                                        if (!mainhand.isEmpty()) {
                                            if (!mainhand.is(ModTag.STICKY_ITEM)) {
                                                int i = mainhand.getCount();
                                                this.koboletonstealdrop(mainhand.copyWithCount(1), target);
                                                target.setItemSlot(EquipmentSlot.MAINHAND, mainhand.split(i - 1));
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

public void tick(){
        super.tick();
        this.prevOnLandProgress = onLandProgress;
        boolean onLand = !this.isInWaterOrBubble() && this.onGround();
        if (onLand && onLandProgress < 5F) {
            onLandProgress++;
        }
        if (!onLand && onLandProgress > 0F) {
            onLandProgress--;
        }
        float targetXRot = 0;
        if(this.getDeltaMovement().length() > 0.09){
            targetXRot = -((float)(Mth.atan2(this.getDeltaMovement().y, this.getDeltaMovement().horizontalDistance()) * (double)Mth.RAD_TO_DEG));
        }
        if(targetXRot < this.getXRot() - 5){
            targetXRot = this.getXRot() - 5;
        }
        if(targetXRot > this.getXRot() + 5){
            targetXRot = this.getXRot() + 5;
        }
        this.setXRot(targetXRot);
        if (!this.level().isClientSide && this.getTarget() != null && this.distanceTo(this.getTarget()) < 2.0F + this.getTarget().getBbWidth()) {
            this.lookAt(this.getTarget(), 350, 200);
            if(this.getAnimation() == ANIMATION_STAB && this.getAnimationTick() == 7 && this.hasLineOfSight(this.getTarget())){
                float f1 = this.getYRot() * Mth.DEG_TO_RAD;
                this.setDeltaMovement(this.getDeltaMovement().add(-Mth.sin(f1) * 0.02F, 0.0D, Mth.cos(f1) * 0.02F));
                getTarget().knockback(1F, getTarget().getX() - this.getX(), getTarget().getZ() - this.getZ());
                this.getTarget().hurt(this.damageSources().mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue());
            }
            if(this.getAnimation() == ANIMATION_SLASH && this.getAnimationTick() % 5 == 0 && this.getAnimationTick() > 0 && this.getAnimationTick() < 25 && this.hasLineOfSight(this.getTarget())){
                for (LivingEntity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.getTarget().getBoundingBox().inflate(2.0D))) {
                    if (!entity.isPassengerOfSameVehicle(this) && entity != this && !entity.isAlliedTo(this)) {
                        entity.hurt(this.damageSources().mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue() * 0.5F);
                    }
                }
            }
        }
        if(onLandProgress >= 5.0F && this.isVehicle()){
            this.ejectPassengers();
        }
        if(!isInWaterOrBubble()){
            if (this.onGround() && random.nextFloat() < 0.2F) {
                this.setDeltaMovement(this.getDeltaMovement().add((this.random.nextFloat() * 2.0F - 1.0F) * 0.2F, 0.5D, (this.random.nextFloat() * 2.0F - 1.0F) * 0.2F));
                this.setYRot(this.random.nextFloat() * 360.0F);
                this.playSound(AMSoundRegistry.SKELEWAG_HURT.get(), this.getSoundVolume(), this.getVoicePitch());
            }
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

@Override
	public boolean run(@NotNull World world, ModuleInstanceEffect instance, @Nonnull SpellData spell, @Nonnull SpellRing spellRing) {
		Entity targetEntity = spell.getVictim(world);
		Entity caster = spell.getCaster(world);

		double potency = spellRing.getAttributeValue(world, AttributeRegistry.POTENCY, spell);

		if (!spellRing.taxCaster(world, spell, true)) return false;

		if (targetEntity instanceof EntityLivingBase) {
			int invTime = targetEntity.hurtResistantTime;
			targetEntity.hurtResistantTime = 0;
			if (targetEntity instanceof EntityPlayer) {

				double targetMana = ManaManager.getMana(targetEntity);

				targetEntity.attackEntityFrom(DamageSource.MAGIC, (float) potency);
				if (targetEntity.isDead) {
					targetMana /= 2;
					targetMana = MathHelper.clamp(targetMana, targetMana, spellRing.getManaDrain(spell) * 2);
					ManaManager.forObject(caster).addMana(targetMana).close();
				}

			} else if (targetEntity instanceof EntityWitch) {

				double targetMana = spellRing.getManaDrain(spell) * 2;

				targetEntity.attackEntityFrom(DamageSource.MAGIC, (float) potency);
				if (targetEntity.isDead) {
					ManaManager.forObject(caster).addMana(targetMana).close();
				}

			} else {
				if (caster instanceof EntityLivingBase) ((EntityLivingBase) caster).setLastAttackedEntity(targetEntity);

				if (caster != null)
					targetEntity.attackEntityFrom(new EntityDamageSource("magic", caster).setDamageBypassesArmor().setMagicDamage(), (float) potency);
				else
					targetEntity.attackEntityFrom(DamageSource.MAGIC, (float) potency);

			}
			targetEntity.hurtResistantTime = invTime;
		}

		Vec3d target = spell.getTargetWithFallback(world);
		if (target != null)
			world.playSound(null, new BlockPos(target), ModSounds.CHAINY_ZAP, CommonProxy.SoundCategory_WizardryGeneral, 0.5f, 1f);
		return true;
	}
